import{_ as l,a0 as o,w as d,s as r,ao as p,I as n,x as s,a1 as i,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"Linux 下如何修改用户名（同时修改用户组名和家目录） | LCTT x X-CMD","titleTemplate":false,"description":"Linux 下如何修改用户名（同时修改用户组名和家目录） | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 下如何修改用户名（同时修改用户组名和家目录） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 下如何修改用户名（同时修改用户组名和家目录） | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171128 How to rename user in Linux (also rename group - home directory)","title":"Linux 下如何修改用户名（同时修改用户组名和家目录）","tag":"201712","desc":""},"relativePath":"201712/20171128 How to rename user in Linux (also rename group - home directory).md","filePath":"[post].md"}'),u={name:"201712/20171128 How to rename user in Linux (also rename group - home directory).md"};function h(g,e,c,k,m,b){const a=o("Link");return d(),r("div",null,[e[13]||(e[13]=p(`<h1 id="linux-下如何修改用户名-同时修改用户组名和家目录" tabindex="-1">Linux 下如何修改用户名（同时修改用户组名和家目录） <a class="header-anchor" href="#linux-下如何修改用户名-同时修改用户组名和家目录" aria-label="Permalink to “Linux 下如何修改用户名（同时修改用户组名和家目录）”">​</a></h1><p>有时候，由于某些原因，我们可能会需要重命名用户名。我们可以很容易地修改用户名以及对应的家目录和 UID。</p><p>本教程将会讨论这些东西。让我们先从修改用户名开始。</p><h3 id="修改用户名" tabindex="-1">修改用户名 <a class="header-anchor" href="#修改用户名" aria-label="Permalink to “修改用户名”">​</a></h3><p>我们使用 <code>usermod</code> 来修改用户名。其语法为，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ usermod -l new_username old_username</span></span></code></pre></div><p>举个例子，假设我们有一个名叫 <code>dan</code> 的用户想要重命名为 <code>susan</code>，那么在终端下执行下面命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo usermod -l susan dan</span></span></code></pre></div><p>这只会更改用户名，而其他的东西，比如用户组，家目录，UID 等都保持不变。</p><p><strong>注意：-</strong> 你需要从要改名的帐号中登出并杀掉该用户的所有进程，要杀掉该用户的所有进程可以执行下面命令，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pkill -u dan</span></span>
<span class="line"><span>$ sudo pkill -9 -u dan</span></span></code></pre></div><h3 id="修改家目录" tabindex="-1">修改家目录 <a class="header-anchor" href="#修改家目录" aria-label="Permalink to “修改家目录”">​</a></h3><p>要同时更改家目录，我们需要在执行 <code>usermod</code> 命令的同时加上 <code>-d</code> 选项，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo usermod -d /home/susan -m susan</span></span></code></pre></div><h3 id="更改用户-uid" tabindex="-1">更改用户 UID <a class="header-anchor" href="#更改用户-uid" aria-label="Permalink to “更改用户 UID”">​</a></h3><p>执行下面命令修改用户 UID，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo usermod -u 2000 susan</span></span></code></pre></div><p>这里 <code>2000</code> 就是用户的新 UID。</p><h3 id="修改用户组名" tabindex="-1">修改用户组名 <a class="header-anchor" href="#修改用户组名" aria-label="Permalink to “修改用户组名”">​</a></h3><p>要把用户组名从 <code>dan</code> 修改为 <code>susan</code>，我们需要使用 <code>groupmod</code> 命令。使用下面命令来修改用户组名，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ groupmod -n susan dan</span></span></code></pre></div><p>做完修改后，可以使用 <code>id</code> 命令来检查，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ id susan</span></span></code></pre></div><p>这篇教导如何修改用户名的指南就此结束了。有任何疑问或建议，欢迎给我们留言。</p><hr>`,25)),n("p",null,[e[1]||(e[1]=s("via: ",-1)),i(a,{href:"http://linuxtechlab.com/rename-user-in-linux-rename-home-directory/"},{default:t(()=>[...e[0]||(e[0]=[s("http://linuxtechlab.com/rename-user-in-linux-rename-home-directory/",-1)])]),_:1})]),n("p",null,[e[5]||(e[5]=s("作者：",-1)),i(a,{href:"http://linuxtechlab.com/author/shsuain/"},{default:t(()=>[...e[2]||(e[2]=[s("Shusain",-1)])]),_:1}),e[6]||(e[6]=s(" 译者：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:t(()=>[...e[3]||(e[3]=[s("lujun9972",-1)])]),_:1}),e[7]||(e[7]=s(" 校对：",-1)),i(a,{href:"https://github.com/wxy"},{default:t(()=>[...e[4]||(e[4]=[s("wxy",-1)])]),_:1})]),n("p",null,[e[10]||(e[10]=s("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[8]||(e[8]=[s("LCTT",-1)])]),_:1}),e[11]||(e[11]=s(" 原创编译，",-1)),i(a,{href:"https://linux.cn/"},{default:t(()=>[...e[9]||(e[9]=[s("Linux中国",-1)])]),_:1}),e[12]||(e[12]=s(" 荣誉推出",-1))])])}const y=l(u,[["render",h]]);export{C as __pageData,y as default};
